/* Fixed numeric ID domains used by Mary-C callable prototypes.
 *
 * Select exactly one of the four ROM targets before including this header.
 * A constant is shared only where independently verified evidence agrees.
 * The current `fomt` source tree is FoMT-US evidence. MFoMT-US and MFoMT-JP
 * semantics must be verified from their respective ROMs, native handlers,
 * scripts, and reliable data.
 *
 * Symbolic and numeric forms are byte-identical; these definitions improve
 * readability and never introduce hidden conversion semantics.
 * Every Mary*Id/Mary*Kind typedef is a compile-time semantic domain only. It
 * is erased to the same integer consumed by the virtual stack and does not
 * change the width, layout, or bytes stored in RIFF/ROM data.
 *
 * Symbol names use the official English terminology of the GBA releases for
 * characters, locations, items, tools, animals, festivals, and other game
 * concepts. Japanese romanization is only a documented fallback for a
 * JP-exclusive proper noun that has no official English counterpart; names
 * introduced by later remakes do not replace the terminology of these ROMs.
 *
 * Mary-C callable 原型使用的固定数字 ID 域。
 *
 * 引用本文件前必须选择四个 ROM 目标之一。只有独立核验的证据一致时，常量才会
 * 定义为共享项。当前 `fomt` 源码树可作为 FoMT-US 证据；MFoMT-US 与 MFoMT-JP
 * 的语义必须分别通过各自 ROM、原生处理函数、脚本及可靠资料确认。
 *
 * 符号形式与数字形式编译出的字节完全一致；这些定义只提高可读性，不引入
 * 隐藏转换语义。
 * 所有 Mary*Id/Mary*Kind typedef 都只是编译期语义域；进入虚拟栈时仍会消除为
 * 同一个整数，不会改变 RIFF/ROM 数据中的宽度、布局或任何字节。
 *
 * 人物、地点、物品、农具、动物、节日及其他游戏概念的符号名，以 GBA 英文版
 * 官方术语为准。日文罗马音只作为“JP 独有且没有官方英文对应名”的明确后备，
 * 后续复刻版采用的新名称不会覆盖本项目四套 ROM 的 GBA 版术语。
 */
#if defined(MARY_FOMT_US)
#define MARY_FOMT
#define MARY_US
#elif defined(MARY_MFOMT_US)
#define MARY_MFOMT
#define MARY_US
#elif defined(MARY_FOMT_JP)
#define MARY_FOMT
#define MARY_JP
#elif defined(MARY_MFOMT_JP)
#define MARY_MFOMT
#define MARY_JP
#endif

/* Complete physical actor-animation ID domain. The contiguous animation
 * record tables end exactly where each ROM's frame-structure array begins:
 * FoMT-US 0x0858BA2C-0x0858E20C and FoMT-JP
 * 0x08311B88-0x08314368 contain 2,552 entries (0-2551); MFoMT-US
 * 0x08522C4C-0x0852557C and MFoMT-JP 0x0852455C-0x08526E8C
 * contain 2,636 entries (0-2635). Numbered names are deliberate: the
 * physical slots are proven, while per-animation official English meanings
 * are not yet independently established. Community catalog labels may be
 * added later only as verified aliases.
 *
 * 完整的角色动画物理 ID 域。每张连续动画记录表都恰好在相应 ROM 的帧结构
 * 数组起点结束：FoMT-US 0x0858BA2C-0x0858E20C 与 FoMT-JP
 * 0x08311B88-0x08314368 各有 2552 项（0-2551）；MFoMT-US
 * 0x08522C4C-0x0852557C 与 MFoMT-JP 0x0852455C-0x08526E8C
 * 各有 2636 项（0-2635）。编号名称是有意采用的中性名称：物理槽已经证实，
 * 但每项动画的官方英文语义尚未逐项独立确认；社区目录名称只能在核实后作为
 * 别名补充。 */
