/* Compatibility aliases preserve existing Mary-C sources that used neutral
 * numbered sequence names before these identities were established. They are
 * accepted by the compiler, while new decompilation uses the semantic names
 * above. IDs 1-17 are corroborated by their native playback sites and matching
 * event contexts in all applicable US/JP FoMT/MFoMT script sets. Record titles
 * and IDs 33-37 additionally match the FoMT-US SongEnt pointers catalogued by
 * FOMT Studio byte-for-byte. IDs 38-42 are selected directly by MFoMT's
 * official US `New Record 1` through `New Record 5` menu entries (the JP menu
 * uses the corresponding `新レコード1` through `新レコード5` labels); FoMT does
 * not expose those five choices in its record-player script. The named SFX
 * entries are restricted to sequences
 * whose calls are paired with the same concrete action or actor in all four
 * vanilla script sets. ID 105 is called only after the hot-spring door closes
 * and immediately before the player's bathing-entry movement; ID 121 is
 * called only after a branch is consumed and immediately before the fireplace
 * is lit. IDs 125-127 occur only at the impact frames of the
 * farming tutorial's hammer demonstrations: one small Stone strike, three
 * repeated large Stone strikes, and six repeated huge Stone strikes. IDs 132
 * and 133 occur at the impact frames for chopping a branch and repeatedly
 * chopping a stump respectively. A direct Sappy sequence comparison also
 * shows why 131, 138, 144, and 145 remain numbered: 125-131 are pitch/duration
 * variants of one hammer timbre, 132-138 are variants of one axe timbre, and
 * 139-145 are variants of one watering-can timbre. MFoMT's blackout scene
 * alternates 144 and 131 between one-frame waits and screen flashes. The
 * MFoMT opening also calls 131 after the protagonist's animation and before
 * Thomas's exclamation or the next scene-state value; its adjacent reaction
 * branches call 138 and 145 after two different player animations and
 * immediately before assigning the next scene-state value. Consequently
 * 131, 138, 144, and 145 are action-synchronized members of their respective
 * tool-timbre families, not blackout- or opening-specific sounds.
 * Call-site timing is audited separately from sequence identity: in MFoMT's
 * New Year's Eve bad-dream event, 170 plays immediately before Karen's attack
 * animation and a screen flash, 174 repeats as individual Harvest Sprites
 * vanish with colored flashes, and 173 follows the final grouped disappearance
 * immediately before the white fade. These timings document their dramatic
 * use, but do not establish sufficiently precise official sound names, so the
 * three IDs remain numbered.
 * An exhaustive scan of the four vanilla Mary-C script sets leaves exactly seven
 * referenced sequences under neutral numbered names: 131, 138, 144, 145, 157,
 * 170, 173, and 174. Every other sequence referenced by an event
 * script has a call-site-supported semantic name; unreferenced physical slots
 * remain numbered because call timing cannot establish their identity.
 * Three reusable cues have deliberately broad names backed by both sequence
 * structure and cross-call-site evidence. ID 157 is a multi-note sequence
 * called after explanatory dialogue and immediately
 * before the medicine or breeding-potion demonstration animation in the
 * chicken, cow, and sheep tutorials; the same ID follows Carter's cursed-tool
 * removal prayer and precedes its sixty-frame pause, hence HEAL_OR_PURIFY rather
 * than a medicine- or curse-specific name. ID 179 is a two-track chiming
 * sequence normally played
 * twice with three-second waits immediately after a wedding fade-in, yet it is
 * also called immediately before the protagonist holds up a top-tier Harvest
 * Goddess TV reward and during the MFoMT opening reaction, hence the neutral
 * CEREMONIAL_CHIME. ID 184 is a short single-note cue called
 * immediately before held-tool presentations, after player exclamation emotes,
 * and on correct quiz outcomes; it is also used during blacksmith and Won
 * interactions, hence ATTENTION_CHIME rather than an emote- or item-specific
 * label.
 * ID 146 is paired both with the watering-can
 * splash and Kappa disappearing into the water, while 188 is paired directly
 * with the shooting-star sparkle effect and the same visual reward sparkle.
 * ID 175 consistently marks elapsed time: it precedes the overnight transition
 * and the crop, chicken, cow, and sheep growth-stage demonstrations in every
 * target. Call timing further distinguishes the reward cues: 176 plays before
 * contest winner announcements and high-tier TV/fishing rewards; 181 plays after the
 * winner dialogue and before the victory pause; 182 plays immediately before
 * the player displays a newly obtained or blessed item. ID 190 brackets the
 * white-flash entrance or departure of the Harvest Goddess in achievements,
 * family events, offerings, and the Golden Lumber reprimand sequence.
 * ID 192 is used only immediately after the player's question-mark emote in
 * the MFoMT Kappa-family scenes; FoMT retains the same physical audio domain.
 * ID 200 has one matching call in every target: during the midnight random
 * scare, Kappa appears immediately above the player, vanishes, the sequence
 * plays, and the player's exclamation and recoil follow.
 * ID 147 is called only after the brush is presented and immediately before the
 * livestock-brushing animation, while 149 is called only immediately before
 * the Doctor's examination animation in all four collapse-recovery scripts.
 * Ambiguous presentation and composite-
 * event sounds keep their numbered names. FOMT Studio's short `sonidos.json`
 * labels are not treated as authoritative where they conflict with these
 * native call sites; its detailed SongEnt-offset CSV is used only where the
 * recorded pointer matches the FoMT-US ROM byte-for-byte.
 *
 * 兼容别名用于继续接受在曲目身份确认前使用中性编号名的既有 Mary-C 源文件；
 * 编译器仍接受这些旧名，但新的反编译输出会使用上方语义名称。编号 1-17 已由
 * 原生播放位置及所有适用的 US/JP FoMT/MFoMT 事件调用上下文交叉确认；唱片名称和
 * 33-37 还与 FOMT Studio 记录的 FoMT-US SongEnt 指针逐字节一致。38-42 由
 * MFoMT 官方英文菜单 `New Record 1` 至 `New Record 5` 直接选择（日文菜单对应为
 * `新レコード1` 至 `新レコード5`）；FoMT 的唱片机脚本没有提供这五个选项。已命名的音效
 * 仅限四套原版脚本都把调用与同一具体动作或角色配对的序列。105 在四个目标中
 * 都只于温泉门关闭后、玩家执行入浴移动前调用；121 都只于树枝被消耗后、壁炉
 * 被点亮前调用。125-127 只出现在
 * 种田教程的锤击命中帧：依次对应敲击一次小石头、重复敲击三次大型石头、重复
 * 敲击六次巨型石头。132、133 分别位于砍断树枝与反复劈砍树桩的命中帧。
 * 对 Sappy 序列的直接比较也说明了为什么 131、138、144、145 继续保留编号：
 * 125-131 是同一锤击音色的音高／时长变体，132-138 是同一斧击音色的变体，
 * 139-145 是同一洒水壶音色的变体。MFoMT 停电演出会在单帧等待与屏幕闪烁之间
 * 交替调用 144 和 131。MFoMT 开场还会在主角动作之后、Thomas 的惊叹号或下一个
 * 场景状态赋值之前调用 131；与其相邻的两种反应分支则会在不同的主角动作之后、
 * 写入下一个场景状态之前分别调用 138 与 145。因此 131、138、144、145 只能确认
 * 是各自工具音色族中与动作同步的成员，不能命名成停电或开场专用音效。调用时机与
 * 序列身份分开审计：在 MFoMT 的除夕噩梦事件中，
 * 170 紧接在 Karen 的攻击动画和屏幕闪烁之前；174 在每个小矮人伴随彩色闪光
 * 消失时重复播放；173 则在最后一组角色消失后、白色淡出前播放。这些时机能够
 * 记录其演出用途，但还不足以证明精确的官方音效名称，因此三个 ID 继续保留编号。
 * 对四套原版 Mary-C 脚本进行完整扫描后，仍以中性编号形式被脚本引用的序列恰好只有
 * 七个：131、138、144、145、170、173、174。其余被事件脚本调用的
 * 序列均已获得调用位置支持的语义名称；从未被脚本引用的物理槽仍保留编号，因为无法
 * 从调用时机证明其身份。另有三个复用提示音采用了同时受音轨结构与跨调用点支持的
 * 宽泛名称。157 是多音符序列，会在鸡、牛、羊教程的说明对白结束后、动物药或奇迹药
 * 演示动作之前调用，也会在 Carter 的解除诅咒农具祈祷之后、六十帧等待之前调用，故命名为
 * HEAL_OR_PURIFY，而不是局限于药物或诅咒。179 是双轨钟琴式序列，通常在婚礼淡入后以三秒
 * 间隔连续播放两次，但也会紧邻女神电视最高级奖励的举物动作，并用于 MFoMT 开场反应。
 * 因而采用中性的 CEREMONIAL_CHIME。184 是短促单音提示，会在举起工具前、玩家惊叹号
 * 表情后及问答正确结果中调用，也会用于铁匠铺和 Won 的互动，故采用 ATTENTION_CHIME，
 * 而不错误限定为某一种表情或物品音效。
 * 146 同时配合洒水壶落水和河童潜入水中的水花动作；188 直接配合流星闪光效果及
 * 相同的奖励闪光表现。175 在四个目标中始终标记时间经过：它位于过夜转场以及
 * 作物、鸡、牛、羊成长阶段演示之前。调用时机还能区分几种奖励提示音：176 位于
 * 比赛获胜公告
 * 及电视／钓鱼高等级奖励之前；181 位于获胜对白之后、胜利停顿之前；182 紧邻
 * 玩家举起新获得或受祝福物品之前；190 则包围女神在成就、家庭、供奉及黄金木材
 * 斥责事件中的白闪出现或离场。192 在 MFoMT 的河童家庭事件中只紧跟玩家问号
 * 表情调用；FoMT 仍保留相同的物理音频取值域。四套 ROM 都只在午夜随机惊吓
 * 事件调用 200：河童在玩家上方瞬间出现并消失，随后播放音效，再触发玩家惊叹号
 * 与后退动作。147 只在展示刷子之后、家畜刷毛动画之前调用；149 在四套
 * 昏倒恢复脚本中都只在医生检查动画之前调用。存在歧义的展示音及复合事件音继续
 * 保留编号名称。FOMT Studio 的
 * 简略 `sonidos.json` 标签若与这些原生调用位置冲突，则不作为权威依据；其详细
 * SongEnt 偏移 CSV 仅在记录指针与 FoMT-US ROM 逐字节相符时采用。 */
