/* Product family selected from a completed blacksmith order. All four
 * targets classify orders 1-30 as tools, 31-34 as accessories, and 35-37 as
 * makers before dispatching the family-specific pickup dialogue and action.
 *
 * 已完成锻冶屋订单的成品类别。四个目标版本都会先将订单 1-30 归为农具、
 * 31-34 归为饰品、35-37 归为加工机，再据此分派对应的领取对话与动作。 */
typedef enum MaryBlacksmithProductCategory
{
    BLACKSMITH_PRODUCT_CATEGORY_TOOL = 0,
    BLACKSMITH_PRODUCT_CATEGORY_ACCESSORY = 1,
    BLACKSMITH_PRODUCT_CATEGORY_MAKER = 2,
} MaryBlacksmithProductCategory;

/* Results returned while placing a completed blacksmith order. The same
 * values cover tools, accessories, and makers in all four targets.
 *
 * 领取锻冶屋成品时返回的放置结果。四个目标版本的农具、饰品和加工机均使用
 * 同一组值。 */
typedef enum MaryBlacksmithCollectionResult
{
    BLACKSMITH_COLLECTION_HELD = 0,
    BLACKSMITH_COLLECTION_RUCKSACK = 1,
    BLACKSMITH_COLLECTION_STORAGE = 2,
    BLACKSMITH_COLLECTION_NO_SPACE = 3,
} MaryBlacksmithCollectionResult;

/* Complete rucksack slot/result domain shared by all four targets. Successful
 * results are zero-based indices in the currently unlocked range; the native
 * upgrade routine proves an eight-slot physical maximum. -1 means that no
 * matching item or free slot exists. FoMT source returns unsigned -1 from all
 * four lookup helpers, and the MFoMT-US/JP native loops independently use the
 * same sentinel. Mary-C emits a named negative constant using the same
 * push-positive followed by integer-negation shape as a source-level `-1`, so
 * decompilation can expose this symbol without changing the original bytes.
 *
 * 四个目标版本共用的完整背包槽／查找结果域。成功时返回当前已解锁背包范围内
 * 从零开始的槽位编号；原生升级函数确认物理上限为八槽。-1 表示没有匹配物品
 * 或空闲槽。FoMT 源码的四个查找函数均返回无符号 -1，MFoMT-US/JP 的原生循环
 * 也分别确认使用相同哨兵值。Mary-C 会把具名负常量编译成与源码字面量 `-1`
 * 相同的“压入正数后取负”结构，因此反编译可以显示该符号而不改变原始字节。 */
typedef enum MaryRucksackSlotIndex
{
    RUCKSACK_SLOT_NOT_FOUND = -1,
    RUCKSACK_SLOT_1 = 0,
    RUCKSACK_SLOT_2 = 1,
    RUCKSACK_SLOT_3 = 2,
    RUCKSACK_SLOT_4 = 3,
    RUCKSACK_SLOT_5 = 4,
    RUCKSACK_SLOT_6 = 5,
    RUCKSACK_SLOT_7 = 6,
    RUCKSACK_SLOT_8 = 7,
} MaryRucksackSlotIndex;

/* Result domain for the held tool-stack count. Positive values are ordinary
 * quantities (1-99) and intentionally remain numeric; -1 is the distinct
 * state in which no valid held tool stack exists. Named negative constants
 * preserve the VM's push-one followed by negation instruction shape, allowing
 * this state to be printed symbolically without weakening byte-exact rebuilds.
 *
 * 手持农具堆数量的返回域。正数 1-99 是普通数量，故意保留数字形式；-1 是
 * 当前不存在有效手持农具堆的独立状态。具名负常量会保留虚拟机“压入 1 后
 * 取负”的指令结构，因此可以在不削弱逐字节重建的前提下输出该状态符号。 */
typedef enum MaryHeldToolStackCount
{
    HELD_TOOL_STACK_NOT_PRESENT = -1,
} MaryHeldToolStackCount;

/* Result domain for AddArticleToRucksack, AddFoodToRucksack, and
 * AddToolToRucksack. Positive values are the ordinary number of copies that
 * did not fit; zero is the semantic state in which the complete request was
 * added.
 *
 * AddArticleToRucksack、AddFoodToRucksack 与 AddToolToRucksack 的返回域。
 * 正数是未能装入的普通剩余数量；0 表示请求数量已全部加入。 */
typedef enum MaryUnaddedItemCount
{
    UNADDED_ITEM_COUNT_NONE = 0,
} MaryUnaddedItemCount;

/* Complete physical chicken-coop feed-trough index domain. The native
 * capacity accessor exposes troughs 1-4 before the coop upgrade and 1-8
 * afterwards; the callable validates an index against that current capacity.
 * Numbering in symbols is one-based for the visible trough, while values are
 * the zero-based indices consumed by the engine.
 *
 * 完整的鸡舍饲料槽物理索引域。原生容量读取在扩建前开放 1-4 号槽，扩建后
 * 开放 1-8 号槽；callable 会按当前容量校验索引。符号按可见饲料槽采用从 1
 * 开始的编号，数值仍是引擎实际使用的从 0 开始索引。 */
typedef enum MaryChickenFeedTroughIndex
{
    CHICKEN_FEED_TROUGH_1 = 0,
    CHICKEN_FEED_TROUGH_2 = 1,
    CHICKEN_FEED_TROUGH_3 = 2,
    CHICKEN_FEED_TROUGH_4 = 3,
    CHICKEN_FEED_TROUGH_5 = 4,
    CHICKEN_FEED_TROUGH_6 = 5,
    CHICKEN_FEED_TROUGH_7 = 6,
    CHICKEN_FEED_TROUGH_8 = 7,
} MaryChickenFeedTroughIndex;

/* Complete physical chicken-incubator index domain. The native capacity is
 * one incubator before the coop upgrade and two afterwards.
 *
 * 完整的鸡舍孵化箱物理索引域。原生容量在扩建前为一个，扩建后为两个。 */
typedef enum MaryChickenIncubatorIndex
{
    CHICKEN_INCUBATOR_1 = 0,
    CHICKEN_INCUBATOR_2 = 1,
} MaryChickenIncubatorIndex;

/* Complete chicken-record slot domain shared by GetPlayerHeldChickenId and
 * chicken-selection interfaces. The native held-item getter accepts only kind
 * 3 and IDs 0-7; every other held-object state returns -1. Selection interfaces
 * use the same -1 value for no selection or cancellation, so the sentinel is
 * deliberately named CHICKEN_SLOT_NONE rather than describing only one caller.
 * The numbered symbols are one-based for human readability, while their values
 * remain the engine's zero-based indices.
 *
 * GetPlayerHeldChickenId 与选鸡界面共用的完整鸡记录槽位域。原生手持物读取
 * 函数仅接受类别 3 及 ID 0-7；其他所有手持物状态均返回 -1。选择界面也以同一
 * -1 表示未选择或取消，因此哨兵有意命名为 CHICKEN_SLOT_NONE，而不只描述某个
 * 调用者。符号为便于阅读采用从 1 开始的编号，实际值仍保持引擎使用的从 0
 * 开始索引。 */
typedef enum MaryChickenSlotIndex
{
    CHICKEN_SLOT_NONE = -1,
    CHICKEN_SLOT_1 = 0,
    CHICKEN_SLOT_2 = 1,
    CHICKEN_SLOT_3 = 2,
    CHICKEN_SLOT_4 = 3,
    CHICKEN_SLOT_5 = 4,
    CHICKEN_SLOT_6 = 5,
    CHICKEN_SLOT_7 = 6,
    CHICKEN_SLOT_8 = 7,
} MaryChickenSlotIndex;

/* Compatibility spelling retained for existing Mary-C sources. New
 * decompilation uses the caller-neutral CHICKEN_SLOT_NONE name.
 *
 * 为既有 Mary-C 源文件保留的兼容名称。新的反编译输出使用不限定调用场景的
 * CHICKEN_SLOT_NONE。 */
mary_const_alias(CHICKEN_SLOT_NOT_HELD, CHICKEN_SLOT_NONE);

