/* Tool categories used by MFoMT's tool-experience query. The public order is
 * sickle, hoe, axe, hammer, watering can, and fishing rod; the engine maps the
 * first two to its older internal hoe/sickle storage order.
 *
 * MFoMT 农具经验查询使用的农具类别。对外顺序依次为镰刀、锄头、斧头、
 * 锤子、洒水壶和钓竿；引擎会把前两项映射到较早的“锄头/镰刀”内部存储顺序。 */
typedef enum MaryToolKind
{
    TOOL_KIND_SICKLE = 0,
    TOOL_KIND_HOE = 1,
    TOOL_KIND_AXE = 2,
    TOOL_KIND_HAMMER = 3,
    TOOL_KIND_WATERING_CAN = 4,
    TOOL_KIND_FISHING_ROD = 5,
} MaryToolKind;

/* Livestock-family selectors used specifically by the festival-entry screen.
 * This domain differs from MaryAnimalKind: chicken is zero here, followed by
 * cow and sheep. All four ROM script sets use the same order.
 *
 * 祭典参赛选择界面专用的家畜类别。该编号域不同于 MaryAnimalKind：鸡为 0，
 * 随后是牛和羊；四套 ROM 脚本使用相同顺序。 */
typedef enum MaryFestivalAnimalKind
{
    FESTIVAL_ANIMAL_CHICKEN = 0,
    FESTIVAL_ANIMAL_COW = 1,
    FESTIVAL_ANIMAL_SHEEP = 2,
} MaryFestivalAnimalKind;

/* Interactive tutorial categories offered by Thomas during the opening farm
 * guidance. All four targets use the same two-value order.
 *
 * Thomas 在开场农场说明中提供的交互式教程类别。四个目标共用相同的两项顺序。 */
typedef enum MaryFarmingTutorialKind
{
    FARMING_TUTORIAL_CROPS = 0,
    FARMING_TUTORIAL_ANIMALS = 1,
} MaryFarmingTutorialKind;

/* Horse-race interface modes confirmed by the race-start and betting branches
 * in all four ROM script sets.
 *
 * 四套 ROM 的正式开赛与下注分支共同确认的赛马界面模式。 */
typedef enum MaryHorseRaceMode
{
    HORSE_RACE_MODE_BETTING = 0,
    HORSE_RACE_MODE_COMPETE = 1,
} MaryHorseRaceMode;

/* Results returned by the horse-race interface in both betting and player-
 * competition modes. All four event scripts dispatch the same four values:
 * -1 cancels the interface, 0 closes without a race result, 1 reports a player
 * victory, and 2 reports a player loss.
 *
 * 赛马界面在投注及玩家参赛模式下返回的结果。四个版本的事件脚本都分派相同的
 * 四个值：-1 表示取消界面，0 表示未产生比赛结果便关闭，1 表示玩家获胜，2 表示
 * 玩家落败。 */
typedef enum MaryHorseRaceInterfaceResult
{
    HORSE_RACE_INTERFACE_CANCELLED = -1,
    HORSE_RACE_INTERFACE_CLOSED_WITHOUT_RESULT = 0,
    HORSE_RACE_INTERFACE_PLAYER_WON = 1,
    HORSE_RACE_INTERFACE_PLAYER_LOST = 2,
} MaryHorseRaceInterfaceResult;

/* Horse-race entry generation modes confirmed by the invitation choice and
 * daily race-state reset scripts in all four targets.
 *
 * 四个目标的参赛邀请选项及每日赛马状态重置脚本共同确认的参赛阵容生成模式。 */
typedef enum MaryHorseRaceEntryMode
{
    HORSE_RACE_ENTRIES_NPC_ONLY = 0,
    HORSE_RACE_ENTRIES_INCLUDE_PLAYER_HORSE = 1,
} MaryHorseRaceEntryMode;

/* Dog-frisbee interface modes confirmed by the beach practice and festival
 * contest scripts in all four targets.
 *
 * 四个目标的海滩自由练习与祭典比赛脚本共同确认的爱犬飞盘界面模式。 */
typedef enum MaryFrisbeeMode
{
    FRISBEE_MODE_PRACTICE = 0,
    FRISBEE_MODE_CONTEST = 1,
} MaryFrisbeeMode;

/* Livestock life-state values stored by the engine for cows, sheep, and
 * chickens. The daily-update code and the animal-death event independently
 * confirm 0 as alive, 1 as natural death, and 2 as death from neglect.
 *
 * 引擎为牛、羊、鸡保存的家畜生命状态。每日更新代码与动物死亡事件分别确认：
 * 0 为存活，1 为自然死亡，2 为照料不当导致的死亡。 */
typedef enum MaryLivestockLifeState
{
    LIVESTOCK_LIFE_STATE_ALIVE = 0,
    LIVESTOCK_LIFE_STATE_DIED_NATURALLY = 1,
    LIVESTOCK_LIFE_STATE_DIED_FROM_NEGLECT = 2,
} MaryLivestockLifeState;

/* Cooking Festival dish-rating results. The native evaluator first checks the
 * current year's dish category, then grades stamina gain minus fatigue gain
 * against that category's thresholds. Event dialogue confirms the five graded
 * tiers; 5 is returned for an invalid or off-theme dish.
 *
 * 料理祭菜品评价结果。原生评价器先检查当年料理类别，再以“体力恢复减疲劳变化”
 * 对照该类别阈值评分。事件对话确认五个评价等级；无效或不合主题的料理返回 5。 */
typedef enum MaryCookingFestivalDishRating
{
    COOKING_FESTIVAL_DISH_RATING_EXCELLENT = 0,
    COOKING_FESTIVAL_DISH_RATING_GREAT = 1,
    COOKING_FESTIVAL_DISH_RATING_GOOD = 2,
    COOKING_FESTIVAL_DISH_RATING_FAIR = 3,
    COOKING_FESTIVAL_DISH_RATING_POOR = 4,
    COOKING_FESTIVAL_DISH_RATING_INELIGIBLE = 5,
} MaryCookingFestivalDishRating;

/* Candidate indices selected for the Moon-Viewing Festival. The engine uses
 * the same numeric range in both games, but each index names a bachelorette
 * in FoMT and a bachelor in MFoMT. The selector prefers the spouse when the
 * player is married; otherwise it chooses among eligible candidates by love,
 * with a random tie break.
 *
 * 赏月节同行候选人的索引。两款游戏使用相同的数字范围，但 FoMT 的每个索引
 * 对应女性候选人，MFoMT 则对应男性候选人。玩家已婚时选择配偶；未婚时按爱情度
 * 从符合条件的候选人中选择，同分时随机决定。 */
typedef enum MaryMoonViewingPartner
{
#if defined(MARY_FOMT)
    MOON_VIEWING_PARTNER_KAREN = 0,
    MOON_VIEWING_PARTNER_ANN = 1,
    MOON_VIEWING_PARTNER_POPURI = 2,
    MOON_VIEWING_PARTNER_MARY = 3,
    MOON_VIEWING_PARTNER_ELLI = 4,
#elif defined(MARY_MFOMT)
    MOON_VIEWING_PARTNER_RICK = 0,
    MOON_VIEWING_PARTNER_CLIFF = 1,
    MOON_VIEWING_PARTNER_KAI = 2,
    MOON_VIEWING_PARTNER_GRAY = 3,
    MOON_VIEWING_PARTNER_DOCTOR = 4,
#endif
} MaryMoonViewingPartner;

/* Fireworks Festival partner-selection values. Zero means no invitation was
 * accepted; values 1-5 identify the accepted standard spouse candidate. The
 * numeric order differs from MaryMoonViewingPartner and is gender-specific.
 *
 * 烟火大会同行对象选择值。0 表示尚未接受任何邀请，1-5 表示已接受邀请的常规
 * 结婚候选人。其编号顺序不同于 MaryMoonViewingPartner，并且男女版分别定义。 */
typedef enum MaryFireworksFestivalPartner
{
    FIREWORKS_FESTIVAL_PARTNER_NONE = 0,
#if defined(MARY_FOMT)
    FIREWORKS_FESTIVAL_PARTNER_KAREN = 1,
    FIREWORKS_FESTIVAL_PARTNER_POPURI = 2,
    FIREWORKS_FESTIVAL_PARTNER_MARY = 3,
    FIREWORKS_FESTIVAL_PARTNER_ELLI = 4,
    FIREWORKS_FESTIVAL_PARTNER_ANN = 5,
#elif defined(MARY_MFOMT)
    FIREWORKS_FESTIVAL_PARTNER_RICK = 1,
    FIREWORKS_FESTIVAL_PARTNER_KAI = 2,
    FIREWORKS_FESTIVAL_PARTNER_CLIFF = 3,
    FIREWORKS_FESTIVAL_PARTNER_GRAY = 4,
    FIREWORKS_FESTIVAL_PARTNER_DOCTOR = 5,
#endif
} MaryFireworksFestivalPartner;

/* Core calendar/time, player-condition, farm-facility, storage, and inventory
 * variables. FoMT's VarGet dispatch reads the player's stored birthday and
 * calls the Farmer stamina/fatigue, FarmHouse, Coop, Barn, and Rucksack
 * getters for the IDs below. MFoMT-US and MFoMT-JP retain equivalent dispatch
 * cases for the proven core fields in this range; ID 53 is deliberately
 * excluded because its two native access paths differ and no vanilla script
 * identifies the field. Vanilla scripts use
 * 8/9 to exclude the player's birthday from other calendar events and use
 * 10-12 for stamina-percentage and fatigue dialogue. The field handlers add
 * one or six units to ID 40 for branches or stumps, while the beehive script
 * reads ID 43 before harvesting and the daily farm update restores it. ID 13
 * is the Mystic Berry state set by ObtainMysticBerry; its Farmer fatigue path
 * halves positive fatigue gain after acquisition. IDs 17-19 are the Mountain,
 * Town, and Seaside Cottage ownership bits. The two event callables set bits 0
 * and 2 respectively, while the Town Cottage inspection/purchase path reads
 * bit 1. FoMT source and both MFoMT ROM regions preserve this ordering.
 * IDs 45-52 expose the step counter, child age/walking state and birthday,
 * elapsed married days, and the stored wedding date. From ID 54 onward the
 * two game families diverge: FoMT enumerates six final love-event timers and
 * five final rival-event timers, whereas MFoMT enumerates eight bachelor love
 * timers and five rival timers. Each helper returns elapsed days only after
 * the engine's final event-count state (5 for player love events, 4 for rival
 * events). The following dog and horse accessors are therefore shifted by two
 * slots in MFoMT. FoMT source establishes the helper contracts; MFoMT-US and
 * MFoMT-JP Ghidra dispatches independently confirm the character order and
 * the shifted animal fields. FoMT ID 53 records whether Ann, Karen, or Popuri
 * continues helping her family business after marriage; MFoMT retains a
 * native field at the corresponding slot but lacks equivalent script evidence
 * and therefore keeps that ID as an explicit UNKNOWN_SLOT placeholder.
 * The named heart-event fields below come from the actual event writers rather
 * than an assumed contiguous layout: every symbol is written by the matching
 * black/purple/blue/yellow-heart, proposal, wedding, or nickname script in
 * both regions. Separate `*_CHOICE` fields are named only where that script
 * demonstrably stores the player's branch result. Unproven gaps deliberately
 * remain explicit UNKNOWN_SLOT placeholders. In particular, MFoMT 86, 94,
 * 96, and 115 have no access in either regional script set; the adjacent Kai,
 * Cliff, and Doctor events do not persist choices there. MFoMT-US/JP Ghidra
 * VarGet tables independently confirm every physical slot from 72 through 120.
 * The five rival-couple groups are likewise named from their four concrete
 * event writers followed by the wedding writer. MFoMT shifts the whole family
 * by eight slots. Rick and Karen alone have a second wedding entry in which
 * Popuri introduces the ceremony; it remains a distinct state field in both
 * games. Neutral event numbers are retained because the local source and ROM
 * evidence proves order and participants, but not an official heart-color
 * label for every rival stage.
 * Each rival wedding then has two boolean control fields. `*_DEFERRED` is set
 * when the player answers “not now”, suppresses the first invitation, and
 * installs the after-work attendance choice. `*_MISSED` is set only when the
 * active wedding reaches the overnight “cannot go outside” cleanup; the next
 * daily update clears it, applies the missed-wedding friendship penalty, and
 * finalizes the couple as married. All four script sets use the same behavior.
 * The first shared town-event block starts at 226 in FoMT and 234 in MFoMT.
 * Matching US/JP dispatchers and event writers prove the same eight-slot
 * gender shift for the festival announcement, collapse recovery, Lillia/Rick/
 * Popuri/Kai family events, Joanna's phone calls, Saibara's visits to Ellen,
 * and Gray's friendship event with Kai. Unused holes remain deliberately
 * unnamed instead of being inferred from adjacency.
 * FoMT 293 and MFoMT 301 are Cliff's collapse-followup delay counters. Their
 * respective daily scripts increment the counter while the adjacent followup
 * state is 1 and complete that state after the counter has passed 2.
 * FoMT 275 and MFoMT 283 are the same extra read-only eligibility gate in
 * Ellen's yarn-gift path: both regions require the slot to equal zero before
 * calling the stocking-knitting event. No vanilla script writes either slot,
 * and the event separately writes VAR_HAS_STOCKING and
 * VAR_ELLEN_KNITS_STOCKING_EVENT_STATE. The slot therefore remains an explicit
 * UNKNOWN_SLOT until its native producer and value contract are proven; it
 * must not be guessed to mean either of those neighboring concepts. The native
 * VarGet dispatchers store an indirect pointer to the first table entry; using
 * that real base proves a one-bit field in both FoMT regions and MFoMT-JP, but
 * a two-bit field in MFoMT-US. The Mary-C bindings preserve this target-specific
 * physical difference without inventing a semantic name.
 * A complete scan of all four vanilla script sets finds no other semantic
 * event producer for a still-unknown event-range slot. Their apparent repeated
 * reads come only from the shared shop-counter guard, which ORs every candidate
 * event field against value 1 to block shopping while any event is active.
 * FoMT slot 449 has one additional write in both regions: the daily world-state
 * reset clears it to zero together with the surrounding seasonal-event fields.
 * That reset establishes daily event-state storage, but neither it nor the
 * generic guard identifies the owning event, so the slot must remain unknown
 * rather than being named from its neighbors.
 * FoMT 420 and MFoMT 464 are the Harvest Festival active lifecycle fields.
 * Festival setup writes 1, normal completion or the following daily rollover
 * writes 2, and an aborted pre-judging exit can restore 0.
 * FoMT 423 and MFoMT 467 are boolean slots immediately after their respective
 * Harvest Festival blocks. Both daily-reset scripts clear them, but no retail
 * script reads either slot or writes a nonzero value. A FoMT native aligned-
 * literal/reference scan likewise finds no direct bit-4 consumer or producer
 * outside the generic accessors. The native VarGet/VarSet tables independently
 * prove that FoMT-US slot 423 is save offset 0x21A0 bit 4 and MFoMT-US slot
 * 467 is save offset 0x21C1 bit 4. Their JP counterparts independently mask
 * the same slots to one bit and store them at bit 4 of offsets 0xA0 and 0xC1
 * respectively in the region-specific save substructure. Physical position
 * and reset grouping still do not prove that either stores a festival result.
 * Both targets therefore retain explicit UNKNOWN_SLOT names with a boolean
 * domain.
 * The four gaps immediately after the special-spouse family blocks are not
 * omitted table entries. FoMT 381-383/385 and MFoMT 411-413/415 each have
 * real two-bit VarGet/VarSet storage handlers. The complete vanilla script
 * corpora only read them through the generic "any event active" guard and
 * contain no individual writer that establishes their meaning. MFoMT-US
 * Ghidra additionally confirms the packed save fields at 0x21B6-0x21B7,
 * while MFoMT-JP independently retains valid handlers despite its regional
 * save-layout packing difference. They therefore remain explicit unknown
 * slots instead of being mislabeled from the neighboring spouse or festival
 * fields.
 * Thanksgiving uses different physical layouts in the two games. In FoMT,
 * 386-390 record the five spring gift exchanges, while 438-447 alternate a
 * candidate's winter visit lifecycle with the pending received-gift marker.
 * In MFoMT, 421-425 record exchange completion for the five standard
 * bachelors, while 428-433 are per-character interaction states reused by
 * winter visits and reciprocal-gift dialogue; the latter group therefore is
 * intentionally not described as a simple boolean visit flag.
 * Two later runtime fields retain the same meaning at gender-specific IDs.
 * GAMECUBE_LINK_LEVEL is the Harvest Goddess mediated GBA/GameCube link
 * progress accumulator (capped at 138 in FoMT and 158 in MFoMT).
 * SHARED_CALLED_SCRIPT_ARGUMENT is the explicit integer channel used to pass
 * context through argument-free CallScript calls; it is transient plumbing,
 * not a persistent story flag.
 * Starry Night is modeled separately. FoMT has five invitation and five
 * candidate-household event fields plus the married farmhouse event. Its next
 * fields are Thomas's winter-25 stocking visit state and route token, followed
 * by the New Year's Eve noodle and New Year sunrise event states. MFoMT has ten
 * invitation fields, five female-friend household
 * events, a shared married-spouse farmhouse event, and five ordered bachelor
 * event slots. Slot 518 is Kai's position immediately before the independently
 * written Cliff, Doctor, Rick, and Gray fields. The daily reset and global
 * event-active guard preserve it even though vanilla winter scheduling leaves
 * no script writer for Kai's reserved event state.
 * FoMT fields 467-481 are one-time recipe-teaching states. Each corresponding
 * character dialogue checks the field, friendship threshold, gift category,
 * and first-gift status before teaching a recipe and setting the field.
 * FoMT fields 482-495 are the television series/program cursors advanced by
 * the Friday daily update. The Harvest Goddess number game also advances its
 * own cursor while a session is being played; Fishing Hour combines its
 * four-entry cursor with the current season.
 * FoMT fields 513-524 guard one-time local GameCube-link milestones. Each is
 * set alongside SetLocalLinkMilestone after its concrete completion predicate
 * succeeds. Slot 523 intentionally describes the shipped predicate literally:
 * it checks mountain cottage twice and seaside cottage once, not town cottage.
 * Received link milestones 39-48 set FoMT fields 496-505 as pending one-shot
 * dialogue notifications for Van, Lou/Ruby, seven named villagers, or the Harvest
 * Sprites. Field 506 separately queues Van's next album-unlock dialogue.
 * Fields 508 and 510 track Lou/Ruby recipes learned and pending respectively.
 * Field 507 brackets a single link-level/recipe update and is independently
 * identified as the GameCube sync-active field; 509 remains an UNKNOWN_SLOT
 * placeholder because its externally-updated contract is incomplete. Fields 511-512 enable the Van
 * and Lou/Ruby introduction events after the corresponding received milestones.
 * The script-visible Jewel of Truth acquisition guards are named by their
 * exact source: refrigerator, calendar, bookshelf, Harvest Goddess math quiz,
 * dog house, street lamp, and water tank. Native merchandise handlers further
 * identify 527 as the 1,000-medal horse-race prize and 528 as Won's item-ID
 * 0x27 offer costing 50,000G.
 * FoMT fields 535 and 537-571, and MFoMT fields 627 and 629-663, are the unlock
 * levels for the 36 A Wonderful Life profiles shown by farmhouse bookshelf
 * reference pages 18-54. Their names follow the explicit ShowReferencePage
 * argument and the MaryReferencePage table, not a positional character guess.
 * Both shipped menus deliberately skip the field corresponding to reference
 * page 50 (Child): FoMT 536 and MFoMT 628 therefore retain UNKNOWN_SLOT placeholders.
 * FoMT daily interaction fields 572-579 cover the day-start golden-lumber
 * snapshot, once-per-day Harvest Goddess/Kappa offerings, their cyclic reward
 * counters, daily confession use, farmhouse entry, and the confessional
 * blessing required by the Harvest Goddess proposal. The offering counters
 * are cyclic cumulative counters, not uninterrupted-day streaks.
 * FoMT fields 581-585 are transient rival-wedding routing states, one for
 * each couple. The event dispatcher sets one when the final rival wedding is
 * due but cannot enter its normal branch immediately; church/entrance routing
 * consumes it, and the daily rollover either clears it after attendance or
 * finalizes the marriage. Field 586 counts elapsed wedding anniversaries and
 * gates the fiftieth-anniversary event. Fields 587-588 guard the one-time
 * Power Berries awarded for winning the horse race and Frisbee tournament.
 * Field 589 is Zack's eight-entry cyclic advice cursor when the shipping bin
 * is empty.
 * FoMT 466 and MFoMT 527 are write-only New Year sunrise scene markers. The
 * byte-identical event position writes 1 after the player reaches the viewing
 * point and immediately before the sunrise-effect callables. Complete vanilla
 * script access and MFoMT native storage-reference analysis find no reader, so
 * the name deliberately describes the observed write rather than claiming the
 * field enables or controls the effect.
 * MFoMT fields 523-526 mirror the verified Thomas stocking visit, route token,
 * New Year's Eve noodle festival, and New Year sunrise lifecycles. Fields
 * 528-532 are the three-state introduction-event lifecycles for Karen, Popuri,
 * Ann, Mary, and Elli.
 * MFoMT fields 533-547 are the same fifteen one-time character recipe lessons
 * as FoMT at their girl-version positions. Fields 548-561 are the corresponding
 * television series/program cursors; both MFoMT regions use the same order.
 * Received MFoMT link milestones 39-48 queue the same ten one-shot dialogue
 * notifications as FoMT in fields 562-571. Later milestones 49-60 use a second
 * topic-specific dialogue family in fields 572-583: Thomas/cooking records,
 * Murrey, the strange forest creature, the valley lizard, Tartan, Hugh's track
 * record, Takakura, Cody, the land turtle, the Chihuahua, Griffin, and the
 * moving teddy bear. The names describe the actual English dialogue topics.
 * MFoMT field 593 is the same GameCube-link update critical-section marker as
 * FoMT 507: both scripts write 1 immediately before updating Lou/Ruby's pending
 * recipe count and restore 0 immediately afterward. Fields 592, 594-596, and
 * 597-598 hold Van's album notification, Lou/Ruby's learned/reward/pending recipe
 * counts, and the Van/Lou-or-Ruby introduction gates. Field 595 is externally
 * read as Lou/Ruby's pending reward-dialogue count. Fields 599-610 are the common local-link milestone guards; 611-615
 * add MFoMT's ten-win guards for Frisbee, horse, chicken, cow, and sheep
 * contests. Field 616 advances Thomas's cooking-record response sequence.
 * The underlying capped win counters are 682-687 in Frisbee, horse, chicken,
 * cow, sheep, and cooking-festival order.
 * MFoMT fields 416-420 are the Spring Thanksgiving cookie exchanges with
 * Karen, Popuri, Mary, Elli, and Ann. Field 434 is Gourmet's corresponding
 * interaction state. Fields 437, 448-449, and 466 are the horse-race session,
 * Frisbee-tournament session/result, and Harvest Festival session phase.
 * Cooking Festival fields 443-445 record whether the player entered, the
 * native six-level dish rating returned by GetCookingFestivalDishRating, and
 * the entered dish's MaryFoodId used to draw its judging-table icon.
 * Fields 689-696 cover the Queen of the Night offering counter, four proven
 * achievement guards, Gourmet's monthly lunch/dinner visits, and the girls'
 * sleepover. Fields 698-702 are the five girls' cooking-request states;
 * 703-704 and 706-707 are Won-event and hundred-question-quiz completion
 * guards. Fields 709-717 record completion of the nine MFoMT television
 * dramas, and 718-720 count large, medium, and small fish in the pond.
 * Slots 697 and 705 have no vanilla script access and retain UNKNOWN_SLOT placeholders.
 * MFoMT fields 478-480 are the three Pumpkin Festival child-visitor
 * lifecycles for May, Stu, and Popuri. Field 481 is the married farmhouse
 * Pumpkin Festival event, and 492 is the married farmhouse Winter
 * Thanksgiving gift event. Field 500 gates Thomas's Winter 23 delivery of
 * Starry Night invitation letters and is completed before he presents the
 * eligible letters. US and JP use the same slots and the same 0=inactive,
 * 1=running, 2=completed lifecycle.
 * Fields 483, 485, 487, 489, 491, and 493-499 record the player's Winter
 * Thanksgiving gift interaction with Popuri, Ann, Elli, Karen, Mary, Kai,
 * Cliff, Doctor, Rick, Gray, Won, and Gourmet in that physical order; the
 * unused gaps remain explicit UNKNOWN_SLOT entries. The shipped Kai dialogue
 * checks Karen's 489 field while selecting its special chocolate response but correctly writes
 * Kai's 493 field afterward. This cross-read is preserved as an original game
 * behavior and is not used to merge the two symbols.
 * FoMT field 250 and MFoMT field 258 record Cliff's permanent winery
 * employment after the corresponding event. Their writers and the surrounding
 * eight-slot event-family shift independently establish the shared meaning.
 * FoMT 412-413 are the cow-festival session and the player's contest result.
 * MFoMT's script-visible Jewel of Truth guards are 618 and 621-626, matching
 * the same seven physical sources as FoMT; native-only 619-620 identify the
 * horse-race prize exchange and Won purchase respectively.
 * Fields 664-670 are the girl-version positions of the day-start golden-lumber
 * snapshot, Goddess/Kappa offering flags and cycles, confession use, and
 * farmhouse entry. Field 671 is specifically the church blessing required for
 * proposing to Kappa. Fields 673-677 are the five rival-wedding routing states,
 * followed by the anniversary count, horse/Frisbee Power Berry guards, and
 * Zack's empty-bin advice cursor in 678-681.
 *
 * 核心日期/时间、玩家状态、农场设施、库存和背包变量。FoMT 的 VarGet
 * 分发表会读取玩家生日，并调用 Farmer 体力/疲劳、FarmHouse、Coop、Barn
 * 和 Rucksack getter；MFoMT-US 与 MFoMT-JP 在此范围保留逐条指令完全相同的
 * 分支。原版脚本用 8/9 在其他日历事件中排除玩家生日，用 10-12 选择体力百分比
 * 与疲劳对话。编号 13 是 ObtainMysticBerry 设置的神秘果实状态；获得后，Farmer
 * 疲劳路径会把正疲劳增量减半。编号 17-19 依次是山中、镇上和海边别墅的所有权
 * 位：两个事件 callable 分别设置第 0、2 位，镇上别墅的查看/购买路径读取第 1 位；
 * FoMT 源码与 MFoMT 两个地区 ROM 都保持这一顺序。田地处理器会在处理树枝/树桩
 * 时分别向编号 40 增加 1/6 份木材；蜂巢脚本会在采蜜前读取编号 43，农场每日
 * 更新会重置它。
 * 编号 45-52 依次公开步数、孩子年龄/学步状态与生日、结婚经过天数及保存的
 * 婚礼日期。从编号 54 起男女版发生分歧：FoMT 依次提供六位结婚候选人的最终
 * 爱情事件计时和五组最终情敌事件计时；MFoMT 则提供八位男性候选人的爱情事件
 * 计时及五组情敌事件计时。只有事件计数达到最终状态时（玩家爱情事件为 5，
 * 情敌事件为 4），底层 helper 才返回经过天数。因此其后的狗与马字段在 MFoMT
 * 中整体后移两个槽。FoMT 源码确认 helper 契约，MFoMT-US/JP 的 Ghidra 分发表
 * 又分别确认人物顺序和动物字段偏移。FoMT 的编号 53 记录 Ann、Karen 或 Popuri
 * 婚后是否继续帮助各自的家庭生意；MFoMT 对应位置虽有原生字段，却没有等价的
 * 脚本证据，因此女孩版仍故意保留明确的 UNKNOWN_SLOT 占位。下方爱情事件字段来自实际写入脚本，
 * 而不是假定连续布局：每个符号都能在两个地区版本对应的黑心、紫心、蓝心、黄心、
 * 求婚、婚礼或昵称脚本中找到写入点。只有脚本明确另存玩家分支结果时才命名
 * `*_CHOICE` 字段，未证实的间隙继续保留 UNKNOWN_SLOT 占位。具体而言，MFoMT
 * 的 86、94、96、115 在 US/JP 两套脚本中均无访问；相邻的 Kai、Cliff、Doctor
 * 事件也没有在这些位置保存选择。MFoMT-US/JP 的 Ghidra VarGet 表又分别确认了
 * 72 到 120 的全部物理槽位。五组竞争情侣也由四个实际事件写入点
 * 加随后的婚礼写入点逐组命名；MFoMT 将整组编号后移八个槽。只有 Rick/Karen
 * 另有一个由 Popuri 引出婚礼的入口，因此两个游戏都保留独立字段。本地源码和
 * ROM 能确认事件顺序及参与人物，但不足以证明每一阶段的官方心色称呼，所以这里
 * 有意使用中性的事件序号。每组竞争情侣婚礼随后还有两个布尔控制字段：玩家回答
 * “现在不参加”时设置 `*_DEFERRED`，它会跳过首次邀请并安装下班后的再次询问；
 * 只有进行中的婚礼拖到过夜、进入“现在不能外出”的清理路径时才设置 `*_MISSED`。
 * 次日更新会清除此值、扣除缺席婚礼的友好度并把情侣婚姻状态最终写成已婚；四套
 * 脚本的行为一致。第一组共通城镇事件变量在 FoMT 从 226 开始，在 MFoMT 从 234
 * 开始。US/JP 对应的派发脚本和事件写入脚本共同确认：节日当日通知、昏倒恢复、
 * Lillia/Rick/Popuri/Kai 家庭事件、Joanna 电话、Saibara 探望 Ellen，以及 Gray
 * 与 Kai 的友情事件都遵循相同的男女版八槽偏移。未使用的间隙有意不命名，不凭
 * 相邻编号推测语义。FoMT 293 与 MFoMT 301 是 Cliff 昏倒后续事件的等待日计数；
 * 各自的每日脚本会在相邻后续状态为 1 时递增计数，并在计数超过 2 后完成该状态。
 * FoMT 275 与 MFoMT 283 是 Ellen 收到毛线时使用的同一项额外只读资格门控：
 * 两个地区版本都要求该槽为 0，才会调用编织袜子事件。四套原版脚本均不写入
 * 该槽，而事件本身另行写入 VAR_HAS_STOCKING 与
 * VAR_ELLEN_KNITS_STOCKING_EVENT_STATE。因此，在原生生产者和值域契约得到证实
 * 之前，该槽继续保留明确的 UNKNOWN_SLOT，不能把它猜成上述任一相邻概念。
 * 原生 VarGet 分派器保存的是指向首个表项的间接指针；按该真实表首对齐后可证明：
 * 两个 FoMT 地区版及 MFoMT-JP 都是一位字段，MFoMT-US 则是两位字段。Mary-C
 * 会保留这项目标版本物理差异，但不会据此虚构语义名。
 * 对四套原版脚本的完整扫描没有发现其他尚未命名事件区间槽的明确事件生产者。
 * 它们看似大量出现的读取全部来自各商店柜台共用的保护条件：该条件把所有候选
 * 事件字段与数值 1 逐项 OR，用来在任一事件活动时禁止购物。FoMT 的 449 在两个
 * 地区版本中另有一处写入：每日世界状态重置会把它与附近的季节事件字段一起清零。
 * 该写入能证明它是每日事件状态存储，却仍不能确定具体归属哪个事件；因此它与
 * 通用保护条件都不足以支持按相邻编号命名，该槽仍必须保留未知。
 * FoMT 420 与 MFoMT 464 是收获祭事件生命周期字段：节日场景初始化时写入 1，
 * 正常结束或随后每日更新时写入 2，评审前中止离场时可以恢复为 0。
 * FoMT 423 与 MFoMT 467 是紧随各自收获祭字段块之后的布尔槽。每日重置脚本会
 * 清零两者，但四套零售脚本都不读取它们，也不写入非零值；对 FoMT 原生对齐
 * 字面量与引用的扫描同样没有在通用访问器之外找到 bit 4 的直接消费者或生产者。
 * 原生 VarGet/VarSet 表分别证明 FoMT-US 槽 423 位于存档偏移 0x21A0 的 bit 4，
 * MFoMT-US 槽 467 位于存档偏移 0x21C1 的 bit 4；对应 JP 版本也各自独立将同一槽
 * 限制为一位，并分别写入地区版存档子结构偏移 0xA0、0xC1 的 bit 4。物理位置和
 * 重置分组仍不足以证明其中任一个保存“收获祭结果”。因此两个目标都保留明确的
 * UNKNOWN_SLOT 名称，同时记录其布尔取值域。
 * 特殊配偶家庭事件块后紧接的四个空缺并不是变量表漏项。FoMT 的 381-383、385
 * 与 MFoMT 的 411-413、415 都有真实的二位宽 VarGet/VarSet 存储处理器；四套
 * 原版脚本只在“任意事件正在进行”的总保护条件中读取这些槽，没有能够证明具体
 * 语义的独立写入点。Ghidra 进一步确认 MFoMT-US 将其打包在存档偏移
 * 0x21B6-0x21B7，而 MFoMT-JP 虽有地区版存档打包差异，也独立保留有效处理器。
 * 因此这些编号继续显式标为未知槽，不能按相邻的配偶或节日字段猜测命名。
 * 感恩祭在两个游戏中采用不同的物理布局：FoMT 的 386-390
 * 记录五位候选人的春季送礼，438-447 则按人物交替存放冬季登门事件生命周期与
 * “已经收到礼物、等待回礼”标记；MFoMT 的 421-425 记录五位常规男候选人的
 * 互赠完成状态，428-433 是按人物保存的交互状态，同时被冬季登门及回礼对话
 * 复用，因此后者不能错误描述成单纯的布尔登门标记。
 * 两个更靠后的运行时字段在男女版使用不同编号但保持相同语义：
 * GAMECUBE_LINK_LEVEL 是由女神界面维护的 GBA/GameCube 联动进度累计值（FoMT
 * 上限 138，MFoMT 上限 158）；SHARED_CALLED_SCRIPT_ARGUMENT 是无参数
 * CallScript 调用之间显式传递整数上下文的临时通道，不是持久剧情 Flag。
 * 星夜祭也按男女版分别建模：FoMT 有五个邀请状态、五个候选人家庭事件状态，
 * 以及一个婚后自宅事件；随后依次是 Thomas 冬 25 日袜子送礼事件及其离场路线
 * 标记、除夕荞麦面祭事件和元旦日出事件。MFoMT 有十个邀请状态、五个女性朋友
 * 家庭聚餐事件、一个婚后自宅配偶事件，以及五个按顺序排列的男候选人事件槽。
 * 518 是 Kai 的位置，紧接其后的是已有独立写入脚本的 Cliff、Doctor、Rick 与
 * Gray。虽然原版冬季日程没有为 Kai 留下脚本写入点，每日重置与全局“事件进行
 * 中”互斥检查仍保留这个预留事件状态槽。
 * FoMT 的 467-481 是一次性料理教学状态：对应人物的对话会先检查该字段、友好度
 * 门槛、礼物类别及当日首次送礼状态，讲授料理后再设置相应字段。
 * FoMT 的 482-495 是由周五每日更新推进的电视连续剧／节目游标。女神猜数字节目
 * 在单次游玩期间还会推进自己的游标；Fishing Hour 则把四项游标与当前季节组合。
 * FoMT 的 513-524 用于防止本地 GameCube 联动里程碑重复登记；每个字段都在相应
 * 完成条件成立并调用 SetLocalLinkMilestone 时写入。523 严格按原版实际条件命名：
 * 脚本检查山中别墅两次和海边别墅一次，并未检查镇上别墅。
 * 收到联动里程碑 39-48 后，FoMT 的 496-505 会分别排队 Van、Lou／Ruby、七位村民或
 * 小矮人的一次性联动对话；506 单独排队 Van 的下一张唱片解锁对话。508 与 510
 * 分别记录已学会及待领取的 Lou／Ruby 料理；507 会包围一次联动等级／料理更新，且
 * 外部状态表独立确认其为 GameCube 同步活动字段；509 的外部更新契约仍不完整，
 * 因此保留 UNKNOWN_SLOT 占位。511-512 在收到对应里程碑后开放 Van 与 Lou／Ruby 的
 * 初次登场事件。
 * 脚本可见的真实之玉取得状态按确切来源命名：冰箱、日历、书架、女神算术问答、
 * 狗屋、路灯和水槽。原生商品处理路径进一步确认 527 是赛马奖品兑换表中价值
 * 1000 枚奖牌的真实之玉，528 是 Won 商品表中 ID 0x27、价格 50000G 的真实之玉。
 * FoMT 的 535、537-571 与 MFoMT 的 627、629-663 是农舍书架资料页 18-54 所显示
 * 的 36 个《A Wonderful Life》人物档案解锁等级。名称依据脚本明确传入的
 * ShowReferencePage 参数及 MaryReferencePage 表，而不是按人物位置猜测。两版
 * 菜单都跳过对应资料页 50（Child）的字段，因此 FoMT 536 与 MFoMT 628 均保留 UNKNOWN_SLOT 占位。
 * FoMT 的每日交互字段 572-579 依次涵盖当日开始时的黄金资材快照、女神／河童
 * 每日一次献礼、两者的循环奖励计数、当日忏悔使用、自宅进入状态，以及向女神
 * 求婚所需的教堂祝福。献礼计数是循环累计值，并不要求连续每天献礼。
 * FoMT 的 581-585 是五组情敌婚礼各自的临时路由状态：最终婚礼到期但无法立即
 * 进入常规分支时由事件派发器写入，教堂／入口路由会读取它，日更则在出席后清除，
 * 或在未处理时完成结婚状态。586 累计已经度过的结婚纪念日，并用于触发第 50 次
 * 结婚纪念事件。587-588 分别防止赛马和飞盘大会冠军力量果实被重复领取；589 是
 * 出货箱为空时 Zack 给出的八条经营建议的循环游标。
 * FoMT 466 与 MFoMT 527 是只写的元旦日出场景标记。两版完全对应的事件都在玩家
 * 到达观景位置后、调用日出特效函数前立即写入 1；完整原版脚本访问记录与 MFoMT
 * 原生存储偏移引用分析均未发现读取者。因此名称只描述已观察到的场景写入，不把
 * 它猜成负责启用或控制特效的开关。
 * MFoMT 的 523-526 依次对应已经确认的 Thomas 袜子送礼事件、离场路线标记、
 * 除夕荞麦面祭事件和元旦日出事件。528-532 是 Karen、Popuri、Ann、Mary、Elli
 * 五个初次见面事件的三阶段生命周期状态。MFoMT 的 533-547 是与男孩版相同的
 * 15 个人物一次性料理教学状态；548-561 是相应的电视连续剧／节目游标，女孩版
 * US/JP 使用相同顺序。
 * MFoMT 收到联动里程碑 39-48 后，会在 562-571 排队与男孩版相同的十组一次性
 * 人物／小矮人对话。里程碑 49-60 在 572-583 使用另一组按主题区分的传闻对话：
 * Thomas／料理大会成绩、Murrey、森林怪物、山谷蜥蜴、Tartan、Hugh 的田径成绩、
 * Takakura、Cody、陆龟、吉娃娃、Griffin 和会动的泰迪熊。名称严格描述英文原版
 * 对话所说的主题。
 * MFoMT 593 与 FoMT 507 是同一个 GameCube 联动更新临界区标记：两版脚本都在
 * 更新 Lou／Ruby 待解锁料理计数前写入 1，完成后立即恢复为 0。592、594-596 与
 * 597-598 分别保存 Van 唱片通知、Lou／Ruby 已学／待播放奖励／待解锁料理数，
 * 以及 Van／Lou-or-Ruby 初次登场开放状态；595 会被该人物对话作为待播放奖励
 * 对话计数读取。
 * 599-610 是男女版共通的本地联动里程碑防重复字段；611-615 额外记录
 * 女孩版飞盘、赛马、鸡、牛、羊大会十胜里程碑。616 推进 Thomas 对料理大会成绩
 * 的分阶段回应。其底层累计胜场位于 682-687，依次为飞盘、赛马、鸡、牛、羊和
 * 料理大会，原版均封顶 100。
 * MFoMT 的 416-420 依次记录与 Karen、Popuri、Mary、Elli、Ann 的春季感恩节
 * 曲奇交换；434 是 Gourmet 的对应互动状态。437、448-449、466 分别是赛马大会
 * 会话状态、飞盘大会会话／结果以及收获祭阶段。料理祭的 443-445 依次记录玩家
 * 是否参赛、GetCookingFestivalDishRating 返回的六级料理评价，以及用于绘制
 * 评审桌图标的参赛料理 MaryFoodId。689-696 包含月下美人献花累计、
 * 四项已证实成就、Gourmet 每月午餐／晚餐来访及女孩留宿事件；698-702 是五位
 * 女孩的料理请求状态，703-704、706-707 是 Won 事件及百问测验完成状态。
 * 709-717 记录女孩版九套电视连续剧完结，718-720 保存鱼塘的大、中、小鱼数量。
 * 697、705 没有原版脚本访问，继续保留 UNKNOWN_SLOT 占位而不猜。
 * MFoMT 的 478-480 分别是 May、Stu、Popuri 三个南瓜祭上门索要点心事件的
 * 生命周期；481 是婚后自宅南瓜祭事件，492 是婚后自宅冬季感恩节送礼事件。
 * 500 控制 Thomas 在冬 23 日送达星夜祭邀请信的事件，并在展示符合条件的邀请信
 * 前写成完成。US 与 JP 使用相同槽位，并采用相同的 0=未激活、1=进行中、
 * 2=完成状态。
 * 483、485、487、489、491 及 493-499 按物理顺序记录玩家在冬季感恩节与
 * Popuri、Ann、Elli、Karen、Mary、Kai、Cliff、Doctor、Rick、Gray、Won、
 * Gourmet 的送礼互动；未使用间隙继续保留显式 UNKNOWN_SLOT。原版 Kai 对话在
 * 选择巧克力专用回应时读取了 Karen 的 489，但随后会正确写入 Kai 的 493。
 * 这是保留的原版交叉读取行为，
 * 不能据此把两个符号合并。
 * FoMT 的 250 与 MFoMT 的 258 都在对应事件后记录 Cliff 已获得酒庄长期工作；
 * 两边的实际写入点以及周围事件族整体后移八槽共同确认了这一共享语义。
 * FoMT 的 412-413 分别是牛祭会话状态和玩家参赛结果。
 * MFoMT 脚本可见的真实之玉取得状态位于 618、621-626，对应与男孩版相同的七个
 * 实体来源；原生路径可见的 619-620 分别对应赛马奖品兑换与 Won 商店购买。664-670 是女孩版的每日开始
 * 黄金资材快照、女神／河童献礼状态与循环计数、忏悔使用和自宅进入字段。671 明确
 * 是向河童求婚所需的教堂祝福。673-677 是五组情敌婚礼路由状态，随后 678-681
 * 依次为结婚纪念日累计、赛马／飞盘力量果实领取状态和 Zack 空出货箱建议游标。
 */
