/* Complete physical map selector domains for the four targets. FoMT uses
 * 0x0000-0x0233 followed by the 0x0234 no-map sentinel. MFoMT inserts six
 * opening-story scene maps at 0x0034-0x0039, shifting both 256-floor mine
 * ranges by six slots and moving the sentinel to 0x023A. The opening script
 * proves that slot 0 is the player's pre-farm home, slots 1-4 are the four
 * silent advertisement-montage maps shown in order, and slot 5 is the scene
 * where the player walks to the telephone and calls the realtor. The montage
 * members retain ordered suffixes because their individual pictured places
 * are not identified. Official English location names are used where a named
 * location exists, and mine floors retain their actual floor numbers on each
 * target.
 *
 * 四个目标的完整物理地图选择域。FoMT 使用 0x0000-0x0233，随后是 0x0234
 * “无地图”哨兵。MFoMT 在 0x0034-0x0039 插入六张开场剧情场景地图，使两段
 * 各 256 层的矿洞地图整体后移六槽，并把哨兵移至 0x023A。开场脚本能够证明：
 * 槽 0 是主角继承牧场前的住处，槽 1-4 是依次播放的四张无对白广告蒙太奇地图，
 * 槽 5 是主角走向电话并致电地产商的场景。由于四张蒙太奇各自描绘的具体地点仍
 * 未确认，它们继续使用有序后缀而不猜测地点。有正式英文地点名的项目使用官方
 * 英文名，矿洞地图则在每个目标中保持真实楼层编号。 */
