/* These slots have not yet been assigned reliable event names. Every listed
 * slot is compared with EVENT_LIFECYCLE_IN_PROGRESS by the shipped global
 * event-exclusion guard, which proves the value domain but not the owning
 * event. Slots 275/283 are deliberately excluded because their only vanilla
 * event-script reads are the Ellen yarn-gift prerequisite described above;
 * their physical widths are target-specific (FoMT 275 and MFoMT-JP 283 are
 * one bit, whereas MFoMT-US 283 is two bits). Slot 449 is cleared by the FoMT daily reset, but has no
 * identified event writer. Keep the physical slot names until a producer or
 * native state contract establishes ownership; nevertheless, render proven
 * lifecycle values symbolically instead of as unexplained integers.
 *
 * 这些槽尚未取得可靠的事件名称。原版全局事件互斥判断会将列出的每个槽与
 * EVENT_LIFECYCLE_IN_PROGRESS 比较；这足以证明取值域，却不能证明槽归属于哪个
 * 事件。275/283 被有意排除，因为原版事件脚本只在上述 Ellen 毛线送礼前置条件中
 * 读取它们；其物理宽度取决于目标版本（FoMT 275 与 MFoMT-JP 283 为一比特，
 * MFoMT-US 283 则为两比特）。449 会被 FoMT 的每日重置清零，但尚未找到对应的事件
 * 写入者。在原生生产者或状态契约能够证明归属前，继续保留物理槽名称，但将已经
 * 证实的生命周期值符号化，避免输出无含义的裸整数。 */
