/* GetAnimalGrowthStage has a species-dependent result domain. These metadata
 * declarations affect only decompiler symbol selection; they compile to no
 * bytecode and leave the callable's physical integer result unchanged.
 *
 * GetAnimalGrowthStage 的返回域取决于动物类别。以下元数据只控制反编译时
 * 选择的符号类型，不生成任何字节码，也不改变 callable 的物理整数返回值。 */
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_HORSE, MaryPetGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_COW, MaryCowGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_SHEEP, MarySheepGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_CHICKEN, MaryChickenGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_DOG, MaryPetGrowthStage);

/* GetPresentedItemId is a category-local ID captured together with
 * GetPresentedItemKind. Inside a branch proven to be FOOD or ARTICLE, its
 * saved result uses the corresponding complete ID domain. Other held kinds
 * deliberately remain integer-valued because they do not share either item
 * table.
 *
 * GetPresentedItemId 是与 GetPresentedItemKind 同时取得的类别内 ID。在已经
 * 证实为 FOOD 或 ARTICLE 的分支中，其保存结果分别使用对应的完整 ID 域。
 * 其他手持类别不属于这两张物品表，故意继续保持整数。 */
mary_callable_return_type_when_callable(GetPresentedItemId, GetPresentedItemKind, HELD_ITEM_KIND_FOOD, MaryFoodId);
mary_callable_return_type_when_callable(GetPresentedItemId, GetPresentedItemKind, HELD_ITEM_KIND_ARTICLE, MaryArticleId);

/* OpenNameEntry's target index is interpreted by the selected naming mode.
 * Cow and sheep names address the shared barn-animal slots, while chicken
 * names address the separate chicken slots. Horse, child, and spouse modes
 * use singleton or reserved targets and deliberately retain an integer index.
 * These declarations affect decompiler symbol selection only.
 *
 * OpenNameEntry 的目标索引由所选命名模式决定。牛、羊名称使用共用的大动物
 * 槽位，鸡名称使用独立的鸡槽位；马、孩子与配偶模式使用单例或保留目标，
 * 因此有意保留整数索引。以下声明仅影响反编译器选择符号。 */
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_COW, 1, MaryAnimalSlotIndex);
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_SHEEP, 1, MaryAnimalSlotIndex);
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_CHICKEN, 1, MaryChickenSlotIndex);

/* The shared livestock handlers use a family-local index. Chicken records
 * occupy the eight-slot coop domain; cow and sheep records occupy the shared
 * sixteen-slot barn domain. The static declarations retain the barn domain as
 * their conservative default, while these metadata bindings recover chicken
 * slot symbols whenever the discriminator proves that family. Contest-entry
 * selectors use their separate FESTIVAL_ANIMAL_* discriminator order.
 *
 * 共用家畜处理函数使用类别内部索引。鸡记录属于八槽鸡舍域，牛羊记录属于共用
 * 的十六槽畜舍域。静态声明以畜舍域作为保守默认值；当判别参数能够证明类别为
 * 鸡时，以下元数据恢复鸡槽位符号。祭典参赛选择器使用另一套
 * FESTIVAL_ANIMAL_* 判别顺序。 */
mary_callable_parameter_type_when(DoesAnimalExist, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalName, 1, ANIMAL_KIND_CHICKEN, 2, MaryChickenSlotIndex);
mary_callable_parameter_type_when(HasAnimalBeenTalkedTo, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(SetAnimalTalkedTo, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(AddAnimalAffection, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(IsAnimalUnhappy, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(IsAnimalSick, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalAge, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalAffection, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_parameter_type_when(SetContestAnimal, 0, ANIMAL_KIND_CHICKEN, 1, MaryChickenSlotIndex);
mary_callable_return_type_when(GetContestAnimalIndex, 0, ANIMAL_KIND_CHICKEN, MaryChickenSlotIndex);
mary_callable_return_type_when(SelectFestivalAnimal, 0, FESTIVAL_ANIMAL_CHICKEN, MaryChickenSlotIndex);
